function __RunAwait_e3d107d0ec6b273effc4($player, $lastDecision = null, $_awaitPc = 0, $_awaitFrameKey = "") {
  $_awaitFrame = DecisionQueueController::GetAwaitFrame($_awaitFrameKey);
  $_awaitLocals = is_array($_awaitFrame) && isset($_awaitFrame['locals']) && is_array($_awaitFrame['locals']) ? $_awaitFrame['locals'] : [];
  if(array_key_exists("mzID", $_awaitLocals)) $mzID = $_awaitLocals["mzID"];
  if(array_key_exists("lookUIDs", $_awaitLocals)) $lookUIDs = $_awaitLocals["lookUIDs"];
  if(array_key_exists("targets", $_awaitLocals)) $targets = $_awaitLocals["targets"];
  if(array_key_exists("chosen", $_awaitLocals)) $chosen = $_awaitLocals["chosen"];
  while(true) {
    switch(intval($_awaitPc)) {
      case 0:
        DecisionQueueController::FinishAwaitFrame($_awaitFrameKey);
        return;
      case 1:
        FaBARCFinishOrder($player, $lookUIDs, '');
        $_awaitPc = 0;
        continue 2;
      case 2:
         FaBARCBanishInstant($player, $chosen, 'Temp');
        $_awaitPc = 1;
        continue 2;
      case 3:
        DecisionQueueController::UpdateAwaitFrame($_awaitFrameKey, ["mzID" => $mzID ?? null, "lookUIDs" => $lookUIDs ?? null, "targets" => $targets ?? null, "chosen" => $chosen ?? null]);
        DecisionQueueController::AddDecision($player, "MZMAYCHOOSE", $targets, 1, "Banish_to_play_as_an_instant");
        DecisionQueueController::AddDecision($player, "CUSTOM", "kano:0:ResolveAbility-await|" . $_awaitFrameKey . "|2|chosen", 1);
        return;
      case 4:
        if($targets !== '') { $_awaitPc = 3; } else { $_awaitPc = 1; }
        continue 2;
      case 5:
        $lookUIDs = FaBARCStageTop($player, 1);
        $targets = FaBARCSelect($player, 'Temp', '', 'NAA');
        $_awaitPc = 4;
        continue 2;
      default:
        DecisionQueueController::FinishAwaitFrame($_awaitFrameKey);
        return;
    }
  }
}

$customDQHandlers["kano:0:ResolveAbility-await"] = function($player, $parts, $lastDecision) { //kano
  $_awaitFrameKey = $parts[0] ?? "";
  $_awaitPc = intval($parts[1] ?? 0);
  $_awaitReturnVar = $parts[2] ?? "";
  if($_awaitReturnVar !== "") {
    DecisionQueueController::StoreVariable($_awaitReturnVar, $lastDecision);
    DecisionQueueController::SetAwaitFrameLocal($_awaitFrameKey, $_awaitReturnVar, $lastDecision);
  }
  __RunAwait_e3d107d0ec6b273effc4($player, $lastDecision, $_awaitPc, $_awaitFrameKey);
};

